callGraph.callee:
tool_calls
            .iter()
            .map(|tc| {
                let arguments: Value =
                    serde_json::from_str(&tc.function.arguments).unwrap_or_else(|err| {
                        warn!(
                            "Failed to parse tool call arguments for '{}': {}",
                            tc.function.name, err
                        );
                        Value::Object(serde_json::Map::new())
                    });

                ToolCallRequest {
                    id: tc.id.clone(),
                    name: tc.function.name.clone(),
                    arguments,
                    thought_signature: tc
                        .extra_content
                        .as_ref()
                        .and_then(|ec| ec.thought_signature().cloned()),
                }
            }).collect

blocks
        .iter()
        .filter_map(|block| {
            let ty = block.get("type").and_then(Value::as_str)?;
            if ty != "image" {
                return None;
            }
            let data = block.get("data").and_then(Value::as_str)?.to_string();
            if data.is_empty() {
                return None;
            }
            let mime = block
                .get("mime_type")
                .and_then(Value::as_str)
                .filter(|m| !m.is_empty())
                .unwrap_or(FALLBACK_MIME)
                .to_string();
            Some((mime, data))
        }).collect

serde_json::from_str(&content)
        .map_err(|err| {
            tracing::warn!(
                "[provider-capabilities] Ignoring invalid cache {}: {}",
                path.display(),
                err
            );
        }).ok

responses_endpoint_reasons
            .iter()
            .map(|(key, reason)| PersistedEndpointReason {
                key: key.clone(),
                reason: reason.clone(),
            }).collect

chat_wire_preferences
            .iter()
            .map(|(key, preference)| PersistedChatWirePreference {
                key: key.clone(),
                preference: preference.clone(),
            }).collect

blocks
        .iter()
        .filter_map(|block| {
            if block.get("type").and_then(Value::as_str)? != "image" {
                return None;
            }
            let data = block.get("data").and_then(Value::as_str)?.to_string();
            if data.is_empty() {
                return None;
            }
            let mime = block
                .get("mime_type")
                .and_then(Value::as_str)
                .filter(|m| !m.is_empty())
                .unwrap_or(FALLBACK_IMAGE_MIME)
                .to_string();
            Some((mime, data))
        }).collect

strip_tool_schema_cache_scopes(tool_list)
            .into_iter()
            .map(|tool| {
                if let Some(func) = tool.get("function") {
                    let mut converted = serde_json::json!({
                        "type": "function",
                    });
                    if let Some(name) = func.get("name") {
                        converted["name"] = name.clone();
                    }
                    if let Some(desc) = func.get("description") {
                        converted["description"] = desc.clone();
                    }
                    if let Some(params) = func.get("parameters") {
                        let mut params = params.clone();
                        enforce_strict_schema(&mut params);
                        converted["parameters"] = params;
                    }
                    converted
                } else {
                    tool.clone()
                }
            }).collect

tools
        .iter()
        .map(|tool| {
            let mut tool = tool.clone();
            strip_tool_schema_cache_scope(&mut tool);
            tool
        }).collect

messages
        .iter()
        .map(|message| {
            let mut sanitized = message.clone();
            if let Some(content) = sanitized.get_mut("content") {
                if let Some(text) = flatten_text_content_with_image_placeholders(content) {
                    *content = Value::String(text);
                }
            }
            sanitized
        }).collect
